    const entry=known.get(file);const st=lstatSync(file);
    if(!entry || !st.isFile() || st.uid!==process.getuid() || st.nlink!==1 || (st.mode&0o777)!==entry.mode || realpathSync(file)!==file || st.size!==entry.bytes || createHash('sha256').update(readFileSync(file)).digest('hex')!==entry.hash)throw Error('S4_D_SOURCE');
