    load(url,context,nextLoad){check(url);if(url.startsWith(pathToFileURL(SOURCE+'/').href) && context.format==='commonjs' && /\.(ts|mts)$/.test(url))throw Error('S4_D_CJS');return nextLoad(url,context);},
